  const handleSaveProject = useCallback(async () => {
    try {
      let finalData = { ...projectFormData };

      // Eğer hotels_data içindeki otellerin id'si yoksa oluştur (sekme silme vs için zorunlu)
      if (finalData.hotels_data && Array.isArray(finalData.hotels_data)) {
        finalData.hotels_data = finalData.hotels_data.map((h: any) => ({
          ...h,
          id: h.id || crypto.randomUUID(),
          hotel_status: h.hotel_status || "BEKLEMEDE"
        }));
      }

      // Boş stringleri null'a çevir (Postgres UUID ve Date hatalarını önlemek için)
      if (finalData.agency_id === "") finalData.agency_id = null;
      if (finalData.hotel_id === "") finalData.hotel_id = null;
      if (finalData.start_date === "") finalData.start_date = null;
      if (finalData.end_date === "") finalData.end_date = null;

      // Proje tamamlandıya çevrildiyse otomatik kilitle
      if (finalData.status === "completed") {
        finalData.locked = true;
      } else {
        // Eğer Super Admin durumu geri aldıysa, kilidi aç
        finalData.locked = false;
      }

      await projectsService.update(projectId, finalData);

      const oldStrategy = project?.exchange_rate_strategy;
      const newStrategy = finalData.exchange_rate_strategy || oldStrategy;

      setProject({ ...project, ...finalData });

      // Proje sorumlularını güncelle
      const updatedProjectUsers = { ...projectUsersMap };
      updatedProjectUsers[projectId] = selectedUsers;
      setProjectUsersMap(updatedProjectUsers);

      // Proje kullanıcılarını Supabase'e kaydet
      await projectUsersService.updateByProjectId(projectId, selectedUsers);

      setIsEditingProject(false);

      // Kur stratejisi değiştiyse arka planda kurları güncelle
      if (
        newStrategy &&
        oldStrategy !== newStrategy &&
        newStrategy !== "manuel"
      ) {
        showNotification(
          "Proje kaydedildi, kurlar güncelleniyor lütfen bekleyin...",
          "info",
        );
        setUpdatingRates(true);
        import("@/lib/api").then(({ api }) => {
          api
            .post(`/api/projects/${projectId}/update-rates`, {
              strategy: newStrategy,
            })
            .then(() => {
              showNotification(
                "Kurlar başarıyla güncellendi! Sayfa yenileniyor...",
                "success",
              );
              setTimeout(() => window.location.reload(), 1500);
            })
            .catch((err) => {
              console.error(err);
              showNotification(
                "Kurlar güncellenirken bir hata oluştu.",
                "danger",
              );
            })
            .finally(() => setUpdatingRates(false));
        });
      } else {
        showNotification("Proje başarıyla güncellendi!", "success");
      }
    } catch (error: any) {
      const errorMessage =
        error?.message ||
        error?.details ||
        (typeof error === "string" ? error : "") ||
        "Proje güncellenirken bir hata oluştu.";
      console.error("Proje güncellenirken hata:", errorMessage, error);
      showNotification(`Proje güncellenirken hata: ${errorMessage}`, "danger");
    }
  }, [projectId, projectFormData, project, projectUsersMap, selectedUsers]);

