  // Acente klavye navigasyonu
  const handleAgencyKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (!showAgencyDropdown) {
        if (e.key === "ArrowDown" || e.key === "Enter") {
          setShowAgencyDropdown(true);
          setSelectedAgencyIndex(0);
        }
        return;
      }

      switch (e.key) {
        case "ArrowDown":
          e.preventDefault();
          setSelectedAgencyIndex((prev) =>
            prev < filteredAgencies.length - 1 ? prev + 1 : 0,
          );
          break;
        case "ArrowUp":
          e.preventDefault();
          setSelectedAgencyIndex((prev) =>
            prev > 0 ? prev - 1 : filteredAgencies.length - 1,
          );
          break;
        case "Enter":
          e.preventDefault();
          if (
            selectedAgencyIndex >= 0 &&
            selectedAgencyIndex < filteredAgencies.length
          ) {
            handleAgencySelect(filteredAgencies[selectedAgencyIndex]);
          }
          break;
        case "Escape":
          setShowAgencyDropdown(false);
          setSelectedAgencyIndex(-1);
          break;
      }
    },
    [
      showAgencyDropdown,
      selectedAgencyIndex,
      filteredAgencies,
      handleAgencySelect,
    ],
  );

