                                            const kur =
                                              parseFloat(e.target.value) || 1.0;
                                            const toplamMaliyet =
                                              tempFlightItem?.toplamMaliyet ||
                                              0;
                                            setTempFlightItem((prev) => ({
                                              ...prev,
                                              kur,
                                              toplamTl: toplamMaliyet * kur,
                                            }));
